#!/usr/bin/env bash
# Question 1: Deployment ${Q1_APP} will not stay scaled. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
rm -rf /opt/course/drift
mkdir -p /opt/course/drift
chown -R ubuntu:ubuntu /opt/course
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
  labels: { app: ${Q1_APP} }
spec:
  replicas: 1
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      terminationGracePeriodSeconds: 1
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF
kubectl -n "${Q1_NS}" rollout status "deployment/${Q1_APP}" --timeout=180s
kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.metadata.uid} {.spec.template.spec}' > "/var/tmp/cka-q1.deploy"
chmod 644 "/var/tmp/cka-q1.deploy"

case "${Q1_FAULT}" in
  hpa-pins-replicas)
    printf '%s\n' "HorizontalPodAutoscaler/${Q1_APP}-capacity" > "/var/tmp/cka-q1.culprit"
    chmod 600 "/var/tmp/cka-q1.culprit"
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"autoscaling/v2","kind":"HorizontalPodAutoscaler","metadata":{"name":"'"${Q1_APP}"'-capacity"},"spec":{"scaleTargetRef":{"apiVersion":"apps/v1","kind":"Deployment","name":"'"${Q1_APP}"'"},"minReplicas":1,"maxReplicas":1,"metrics":[{"type":"Resource","resource":{"name":"cpu","target":{"type":"Utilization","averageUtilization":80}}}]}}' >/dev/null
    ;;
  cronjob-reverts)
    printf '%s\n' 'CronJob/capacity-guard' > "/var/tmp/cka-q1.culprit"
    chmod 600 "/var/tmp/cka-q1.culprit"
    kubectl create namespace "cluster-tools" >/dev/null 2>&1 || kubectl get namespace "cluster-tools" >/dev/null
    timeout 60 bash -c "until kubectl -n 'cluster-tools' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
    kubectl -n cluster-tools create serviceaccount capacity-guard --dry-run=client -o yaml | kubectl apply -f - >/dev/null
    kubectl -n "${Q1_NS}" create role capacity-guard --verb=get,patch,update --resource=deployments,deployments/scale --dry-run=client -o yaml | kubectl apply -f - >/dev/null
    kubectl -n "${Q1_NS}" create rolebinding capacity-guard --role=capacity-guard --serviceaccount=cluster-tools:capacity-guard --dry-run=client -o yaml | kubectl apply -f - >/dev/null
    kubectl -n cluster-tools apply -f - <<< '{"apiVersion":"batch/v1","kind":"CronJob","metadata":{"name":"capacity-guard"},"spec":{"schedule":"* * * * *","concurrencyPolicy":"Forbid","successfulJobsHistoryLimit":1,"failedJobsHistoryLimit":1,"jobTemplate":{"spec":{"backoffLimit":0,"template":{"spec":{"serviceAccountName":"capacity-guard","restartPolicy":"Never","containers":[{"name":"guard","image":"busybox:1.36","command":["/host/kubectl","-n","'"${Q1_NS}"'","scale","deployment/'"${Q1_APP}"'","--replicas=1"],"volumeMounts":[{"name":"kubectl","mountPath":"/host/kubectl"}]}],"volumes":[{"name":"kubectl","hostPath":{"path":"/usr/bin/kubectl","type":"File"}}]}}}}}}' >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=4

case "${Q1_FAULT}" in
  hpa-pins-replicas)
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.spec.replicas}')" != 4 ]] && exit 0
      sleep 2
    done
    echo "${Q1_APP} kept its 4 replicas" >&2
    exit 1
    ;;
  cronjob-reverts)
    kubectl -n cluster-tools create job capacity-guard-first --from=cronjob/capacity-guard >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.spec.replicas}')" != 4 ]] && exit 0
      sleep 2
    done
    echo "${Q1_APP} kept its 4 replicas" >&2
    exit 1
    ;;
esac
